// 2. Validate Input
// Confirms the enriched alarm from WF-04 has everything the correlation
// engine needs to group and deduplicate it correctly.

const REQUIRED = ['correlationId', 'siteId', 'nodeName', 'alarmType', 'timestamp', 'region', 'vendor'];

const item = $input.first().json;
const missing = REQUIRED.filter((f) => item[f] === undefined || item[f] === null || item[f] === '');

return [{
  json: {
    isValid: missing.length === 0,
    missingFields: missing,
    ...item
  }
}];

// 3. Correlation & Deduplication Engine
// Core stateful logic. Uses n8n's built-in workflow static data as the
// incident store (see README for production scaling notes).
//
// Rule 1: same correlationId seen before -> exact duplicate, ignore.
// Rule 2: same grouping key (fiberRoute, or siteId if no route) with an
//         OPEN incident (last alarm within the 5-minute window) -> merge
//         as a child alarm into that incident (this is how a Fiber Cut's
//         cascading LOS/High BER/etc. alarms all fold into one incident).
// Rule 3: otherwise -> create a new master incident.
//
// A lightweight retention prune runs on every execution to keep the store
// bounded (removes incidents/index entries older than RETENTION_MS).

const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');

if (!staticData.incidents) staticData.incidents = {};
if (!staticData.correlationIdIndex) staticData.correlationIdIndex = {};
if (!staticData.groupIndex) staticData.groupIndex = {};

const WINDOW_MS = 5 * 60 * 1000; // 5-minute correlation window
const RETENTION_MS = 24 * 60 * 60 * 1000; // 24-hour retention for pruning
const nowMs = Date.now();

function isExpired(incident, windowMs) {
  return (nowMs - new Date(incident.lastAlarmAt).getTime()) > windowMs;
}

// --- Retention pruning (bounds memory growth; see README Performance Optimization) ---
for (const cid of Object.keys(staticData.correlationIdIndex)) {
  const incId = staticData.correlationIdIndex[cid];
  const inc = staticData.incidents[incId];
  if (!inc || isExpired(inc, RETENTION_MS)) delete staticData.correlationIdIndex[cid];
}
for (const key of Object.keys(staticData.groupIndex)) {
  const incId = staticData.groupIndex[key];
  const inc = staticData.incidents[incId];
  if (!inc || isExpired(inc, RETENTION_MS)) delete staticData.groupIndex[key];
}
for (const incId of Object.keys(staticData.incidents)) {
  const inc = staticData.incidents[incId];
  if (isExpired(inc, RETENTION_MS)) delete staticData.incidents[incId];
}

// --- Rule 1: exact duplicate (same correlationId already processed) ---
if (staticData.correlationIdIndex[item.correlationId]) {
  const incidentId = staticData.correlationIdIndex[item.correlationId];
  const incident = staticData.incidents[incidentId];
  incident.duplicateCount = (incident.duplicateCount || 0) + 1;
  incident.lastAlarmAt = new Date().toISOString();

  return [{
    json: {
      outcome: 'duplicate_ignored',
      incidentId: incident.incidentId,
      rootAlarm: incident.rootAlarm,
      childAlarms: incident.childAlarms,
      occurrenceCount: incident.occurrenceCount,
      duplicateCount: incident.duplicateCount,
      impact: incident.impact,
      affectedCustomers: incident.affectedCustomers,
      businessPriority: incident.businessPriority,
      siteId: incident.siteId,
      fiberRoute: incident.fiberRoute,
      vendor: incident.vendor,
      region: incident.region,
      createdAt: incident.createdAt,
      lastAlarmAt: incident.lastAlarmAt
    }
  }];
}

// --- Grouping key: prefer fiber route (catches multi-site route-level incidents), fall back to Site ID ---
const groupKey = item.fiberRoute ? `route:${item.fiberRoute}` : `site:${item.siteId}`;

const existingIncidentId = staticData.groupIndex[groupKey];
const existingIncident = existingIncidentId ? staticData.incidents[existingIncidentId] : null;

// --- Rule 2: merge into an open incident for this group within the 5-minute window ---
if (existingIncident && !isExpired(existingIncident, WINDOW_MS)) {
  existingIncident.childAlarms.push({
    correlationId: item.correlationId,
    alarmType: item.alarmType,
    nodeName: item.nodeName,
    priority: item.priority || null,
    timestamp: item.timestamp
  });
  existingIncident.occurrenceCount = existingIncident.childAlarms.length + 1; // +1 for the root alarm
  existingIncident.lastAlarmAt = new Date().toISOString();
  existingIncident.affectedCustomers = Math.max(existingIncident.affectedCustomers || 0, item.customerCount || 0);

  staticData.correlationIdIndex[item.correlationId] = existingIncident.incidentId;

  return [{
    json: {
      outcome: 'merged_child',
      incidentId: existingIncident.incidentId,
      rootAlarm: existingIncident.rootAlarm,
      childAlarms: existingIncident.childAlarms,
      occurrenceCount: existingIncident.occurrenceCount,
      duplicateCount: existingIncident.duplicateCount || 0,
      impact: existingIncident.impact,
      affectedCustomers: existingIncident.affectedCustomers,
      businessPriority: existingIncident.businessPriority,
      siteId: existingIncident.siteId,
      fiberRoute: existingIncident.fiberRoute,
      vendor: existingIncident.vendor,
      region: existingIncident.region,
      createdAt: existingIncident.createdAt,
      lastAlarmAt: existingIncident.lastAlarmAt
    }
  }];
}

// --- Rule 3: create a new master incident ---
const incidentId = 'INC-' + nowMs + '-' + Math.random().toString(36).slice(2, 8).toUpperCase();
const nowIso = new Date().toISOString();

const incident = {
  incidentId,
  siteId: item.siteId,
  fiberRoute: item.fiberRoute || null,
  vendor: item.vendor,
  region: item.region,
  rootAlarm: {
    correlationId: item.correlationId,
    alarmType: item.alarmType,
    nodeName: item.nodeName,
    priority: item.priority || null,
    timestamp: item.timestamp
  },
  childAlarms: [],
  occurrenceCount: 1,
  duplicateCount: 0,
  impact: item.customerImpact || item.impact || null,
  businessPriority: item.businessPriority || null,
  affectedCustomers: item.customerCount || 0,
  createdAt: nowIso,
  lastAlarmAt: nowIso
};

staticData.incidents[incidentId] = incident;
staticData.groupIndex[groupKey] = incidentId;
staticData.correlationIdIndex[item.correlationId] = incidentId;

return [{
  json: {
    outcome: 'new_master_incident',
    incidentId: incident.incidentId,
    rootAlarm: incident.rootAlarm,
    childAlarms: incident.childAlarms,
    occurrenceCount: incident.occurrenceCount,
    duplicateCount: incident.duplicateCount,
    impact: incident.impact,
    affectedCustomers: incident.affectedCustomers,
    businessPriority: incident.businessPriority,
    siteId: incident.siteId,
    fiberRoute: incident.fiberRoute,
    vendor: incident.vendor,
    region: incident.region,
    createdAt: incident.createdAt,
    lastAlarmAt: incident.lastAlarmAt
  }
}];
